    [FunctionalTheory][InlineData(0,false)][InlineData(0,true)][InlineData(2,false)][InlineData(2,true)]
    public async Task GivenAccountWideAccess_WhenCreatingWithOwnedRelationships_ThenPersistOnlyNewCiphertextLinksAndParentMetadata(int profiles,bool folder)
    {
        using var owner=new ProtectionFixture();using var first=new ProtectionFixture();using var second=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var f=folder?await Folder(s):null;var parents=new List<Profile>();if(profiles>0){parents.Add(await Profile(s,owner,first,f));parents.Add(await Profile(s,owner,second,f));}var input=Input(parents.Select(p=>p.PublicId).ToArray(),f?.PublicId);var protectedBefore=await Protected(s);var result=await Store().CreateAsync(new(s.Actor,s.Verifier,input),default);
        Assert.Null(result.Error);Assert.Equal(input.RecordId,result.Data!.RecordId);Assert.Equal(1,result.Data.Revision);Assert.True(result.Data.ServerSequence>0);Assert.Equal(Normalize(input.EditedAt),result.Data.EditedAt);Assert.Equal(protectedBefore,await Protected(s));await using var db=fixture.CreateContext();var row=await db.Records.SingleAsync(x=>x.PublicId==input.RecordId);Assert.Equal(s.InternalId,row.AccountId);Assert.Equal(JsonSerializer.SerializeToUtf8Bytes(input.Envelope,ProtectionFixture.Json),row.Envelope);Assert.Equal(f?.Id,row.FolderId);Assert.Equal(result.Data.ServerSequence,row.ServerSequence);Assert.Null(row.DeletedAt);Assert.Null(row.PurgeAt);Assert.Equal(parents.Select(p=>p.Id).Order(),await db.ProfileRecords.Where(x=>x.RecordId==row.Id).OrderBy(x=>x.ProfileId).Select(x=>x.ProfileId).ToArrayAsync());
        foreach(var p in parents){var current=await db.Profiles.AsNoTracking().SingleAsync(x=>x.Id==p.Id);Assert.Equal(p.Revision+1,current.Revision);Assert.True(current.ServerSequence>p.ServerSequence);Assert.Equal(p.EditedAt,current.EditedAt);Assert.Equal(p.Envelope,current.Envelope);Assert.Equal(p.KeyWrappers,current.KeyWrappers);var view=await new ProfileReadStore(fixture).ReadAsync(new(s.Actor,s.Verifier,p.PublicId),default);Assert.Contains(input.RecordId,view.Data!.RecordIds);Assert.Equal(f is null?Array.Empty<Guid>():[f.PublicId],view.Data.FolderIds);}
        if(f is not null){var current=await db.Folders.AsNoTracking().SingleAsync(x=>x.Id==f.Id);Assert.Equal(f.Revision+1,current.Revision);Assert.True(current.ServerSequence>f.ServerSequence);Assert.Equal(f.Envelope,current.Envelope);Assert.Equal(f.EditedAt,current.EditedAt);}
    }
