        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var foreign=await ProfileSetup.Create(fixture,owner);var p=await Profile(kind=="profileForeign"?foreign:s,owner,scoped);var root=await Folder(kind=="folderForeign"?foreign:s);var folder=kind.StartsWith("ancestor",StringComparison.Ordinal)?await Folder(s,root.Id):root;var input=Input([kind=="profileMissing"?Guid.NewGuid():p.PublicId],kind=="folderMissing"?Guid.NewGuid():folder.PublicId);var actor=s.Actor;
        await using(var db=fixture.CreateContext()){if(kind=="profileTrash")await db.Profiles.Where(x=>x.Id==p.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind is "folderTrash" or "ancestorTrash")await db.Folders.Where(x=>x.Id==(kind=="folderTrash"?folder.Id:root.Id)).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind=="closing")await db.Accounts.Where(x=>x.Id==s.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.State,AccountState.ClosurePending));if(kind is "profileTerminal" or "folderTerminal" or "ancestorTerminal" or "accountTerminal")db.TerminalErasures.Add(new(){ResourceId=kind=="profileTerminal"?p.PublicId:kind=="accountTerminal"?s.AccountId:kind=="ancestorTerminal"?root.PublicId:folder.PublicId,ResourceKind=kind=="profileTerminal"?"profile":kind=="accountTerminal"?"account":"folder",DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();if(kind=="accountMissing")actor=Guid.NewGuid();}
