    [FunctionalTheory][InlineData("missing")][InlineData("revoked")][InlineData("expired")][InlineData("future")][InlineData("policy")][InlineData("generation")][InlineData("danglingSelection")][InlineData("foreignSelection")][InlineData("trashedSelection")][InlineData("terminalSelection")][InlineData("disabledWithExpiry")]
    public async Task GivenInvalidCurrentSession_WhenCreating_Then403WithoutMutation(string kind)
