        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var foreign=await ProfileSetup.Create(fixture,owner);var p=await Profile(kind=="foreignSelection"?foreign:s,owner,scoped);var verifier=s.Verifier;
        await using(var db=fixture.CreateContext()){var v=await db.VaultAccessSessions.SingleAsync(x=>x.AccountId==s.InternalId);if(kind=="missing")verifier="missing";if(kind=="revoked")v.Revoked=true;if(kind=="expired")v.ExpiresAt=DateTimeOffset.UtcNow.AddSeconds(-1);if(kind=="future")v.IssuedAt=DateTimeOffset.UtcNow.AddHours(1);if(kind=="policy")v.PolicyRevision++;if(kind=="generation")v.RevocationGeneration++;if(kind=="danglingSelection")v.ProfileId=long.MaxValue;if(kind is "foreignSelection" or "trashedSelection" or "terminalSelection")v.ProfileId=p.Id;if(kind=="trashedSelection")await db.Profiles.Where(x=>x.Id==p.Id).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.DeletedAt,DateTimeOffset.UtcNow));if(kind=="terminalSelection")db.TerminalErasures.Add(new(){ResourceId=p.PublicId,ResourceKind="profile",DeletedAt=DateTimeOffset.UtcNow});if(kind=="disabledWithExpiry")await db.Accounts.Where(x=>x.Id==s.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(a=>a.RenewalEnabled,false));await db.SaveChangesAsync();}
        var before=await Snapshot(s);var result=await Store().CreateAsync(new(s.Actor,verifier,Input([p.PublicId])),default);Assert.Equal("vault_access_denied",result.Error);Assert.Null(result.Data);Assert.Equal(before,await Snapshot(s));
    }
