    [FunctionalTheory][InlineData("account")][InlineData("session")][InlineData("profile")][InlineData("folder")]
    public async Task GivenAccessExpiresDuringLockWait_WhenCreating_Then403AndNoWrites(string kind)
    {using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var folder=await Folder(s);var p=await Profile(s,owner,scoped,folder);var deadline=await Short(s);var before=await Snapshot(s);await using var held=fixture.CreateContext();await using var tx=await held.Database.BeginTransactionAsync();if(kind=="account")await held.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.account WHERE id={s.InternalId} FOR UPDATE");if(kind=="session")await held.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.vault_access_session WHERE account_id={s.InternalId} FOR UPDATE");if(kind=="profile")await held.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.profile WHERE id={p.Id} FOR UPDATE");if(kind=="folder")await held.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM cerberus.folder WHERE id={folder.Id} FOR UPDATE");var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var pending=new RecordCreateStore(new ProfileSetup.Factory(fixture,new Signal(reached,kind))).CreateAsync(new(s.Actor,s.Verifier,Input([p.PublicId],folder.PublicId)),default);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(pending.IsCompleted);await Past(deadline);await tx.CommitAsync();var result=await pending;Assert.Equal("vault_access_denied",result.Error);Assert.Null(result.Data);Assert.Equal(before,await Snapshot(s));}
