    [FunctionalTheory][InlineData("afterInsert")][InlineData("afterParent")][InlineData("link")]
    public async Task GivenPostInsertFailure_WhenCreating_ThenRollbackRecordLinksAndParentsAndRetrySameId(string kind)
    {using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var folder=await Folder(s);var p=await Profile(s,owner,scoped,folder);var input=Input([p.PublicId],folder.PublicId);var before=await Snapshot(s);await using var db=fixture.CreateContext();if(kind=="link")await db.Database.ExecuteSqlRawAsync("CREATE FUNCTION cerberus.reject_record_create_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic link failure' USING ERRCODE='08006'; END $$; CREATE TRIGGER reject_record_create_fixture BEFORE INSERT ON cerberus.profile_record FOR EACH ROW EXECUTE FUNCTION cerberus.reject_record_create_fixture();");try{var store=kind=="link"?Store():new RecordCreateStore(new ProfileSetup.Factory(fixture,new Fail(kind)));var result=await store.CreateAsync(new(s.Actor,s.Verifier,input),default);Assert.Equal("persistence_unavailable",result.Error);Assert.Null(result.Data);Assert.Equal(before,await Snapshot(s));}finally{if(kind=="link")await db.Database.ExecuteSqlRawAsync("DROP TRIGGER IF EXISTS reject_record_create_fixture ON cerberus.profile_record; DROP FUNCTION IF EXISTS cerberus.reject_record_create_fixture();");}Assert.Null((await Store().CreateAsync(new(s.Actor,s.Verifier,input),default)).Error);}
