    [FunctionalTheory][InlineData("actor")][InlineData("id")][InlineData("null")][InlineData("time")][InlineData("profiles")]
    public async Task GivenInvalidTrustedInput_WhenCreating_ThenRejectBeforeDeadDependency(string kind)
    {using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var input=Input();input=kind switch{"id"=>input with{RecordId=Guid.Empty},"null"=>null!,"time"=>input with{EditedAt=new(9,TimeSpan.Zero)},"profiles"=>input with{ProfileIds=null!},_=>input};var result=await Dead().CreateAsync(new(kind=="actor"?Guid.Empty:s.Actor,s.Verifier,input),default);Assert.Equal(kind=="actor"?"authentication_required":"validation_failed",result.Error);Assert.Null(result.Data);}
    [FunctionalFact]
    public async Task GivenUnavailablePersistenceOrCancelledCaller_WhenCreating_ThenFailClosedOrPropagateCancellation()
    {using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var before=await Snapshot(s);var r=await Dead().CreateAsync(new(s.Actor,s.Verifier,Input()),default);Assert.Equal("persistence_unavailable",r.Error);Assert.Null(r.Data);using var source=new CancellationTokenSource();source.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>Store().CreateAsync(new(s.Actor,s.Verifier,Input()),source.Token));Assert.Equal(before,await Snapshot(s));}
    private RecordCreateStore Store()=>new(fixture);
    private static RecordCreateStore Dead()=>new(new ProfileSetup.Factory(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql("Host=127.0.0.1;Port=1;Database=unavailable;Username=none;Timeout=1;Pooling=false").Options));
    private static RecordCreateInput Input(Guid[]? profiles=null,Guid? folder=null)=>new(Guid.NewGuid(),ProfileSetup.Envelope(),DateTimeOffset.UnixEpoch.AddTicks(19),profiles??[],folder);
    private static DateTimeOffset Normalize(DateTimeOffset value)=>value.AddTicks(-(value.Ticks%TimeSpan.TicksPerMicrosecond));
    private async Task<Profile> Profile(ProfileSetup.State s,ProtectionFixture owner,ProtectionFixture scoped,VaultFolder? folder=null){var input=ProfileSetup.Input(s,owner,scoped);if(folder is not null)input=input with{FolderIds=[folder.PublicId]};Assert.Null((await new ProfileCreateStore(fixture).CreateAsync(new(s.Actor,s.Verifier,input),default)).Error);await using var db=fixture.CreateContext();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==input.ProfileId);}
    private async Task<VaultFolder> Folder(ProfileSetup.State s,long? parent=null){var folder=new VaultFolder{PublicId=Guid.NewGuid(),AccountId=s.InternalId,ParentFolderId=parent,Envelope=JsonSerializer.SerializeToUtf8Bytes(ProfileSetup.Envelope(),ProtectionFixture.Json),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.CreateContext();db.Folders.Add(folder);await db.SaveChangesAsync();return folder;}
    private async Task<string> Selected(ProfileSetup.State s,long id){var verifier=Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32));await using var db=fixture.CreateContext();db.VaultAccessSessions.Add(new(){AccountId=s.InternalId,ProfileId=id,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=1,RevocationGeneration=1});await db.SaveChangesAsync();return verifier;}
    private async Task<DateTimeOffset> Short(ProfileSetup.State s){var deadline=DateTimeOffset.UtcNow.AddSeconds(2);await using var db=fixture.CreateContext();await db.VaultAccessSessions.Where(x=>x.AccountId==s.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.ExpiresAt,deadline));return deadline;}
    private static async Task Past(DateTimeOffset deadline){var remaining=deadline-DateTimeOffset.UtcNow;if(remaining>TimeSpan.Zero)await Task.Delay(remaining+TimeSpan.FromMilliseconds(120));}
    private async Task<string> Protected(ProfileSetup.State s){await using var db=fixture.CreateContext();return JsonSerializer.Serialize(new{Account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==s.InternalId),Protection=await db.VaultProtections.AsNoTracking().SingleAsync(x=>x.AccountId==s.InternalId),Sessions=await db.VaultAccessSessions.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync()});}
    private async Task<string> Snapshot(ProfileSetup.State s){await using var db=fixture.CreateContext();return JsonSerializer.Serialize(new{Protected=await Protected(s),Records=await db.Records.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Profiles=await db.Profiles.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Folders=await db.Folders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),ProfileRecords=await db.ProfileRecords.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.RecordId).ToArrayAsync(),ProfileFolders=await db.ProfileFolders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.FolderId).ToArrayAsync()});}
    private sealed class Signal(TaskCompletionSource reached,string kind):DbCommandInterceptor{public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("FOR UPDATE") && c.CommandText.Contains(kind=="account"?"cerberus.account":kind=="session"?"cerberus.vault_access_session":kind=="profile"?"cerberus.profile":"cerberus.folder"))reached.TrySetResult();return ValueTask.FromResult(r);}}
    private sealed class Expire(DateTimeOffset deadline):DbCommandInterceptor{public override async ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("INSERT INTO cerberus.record"))await Past(deadline);return r;}}
    private sealed class Terminal(PostgresFixture fixture,Guid id,string kind):DbCommandInterceptor{public override async ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<int> r,CancellationToken ct=default){if(c.CommandText.Contains("INSERT INTO cerberus.record")){await using var db=fixture.CreateContext();db.TerminalErasures.Add(new(){ResourceId=id,ResourceKind=kind,DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync(ct);}return r;}}
    private sealed class Fail(string kind):DbCommandInterceptor
    {
        private bool inserted;
        public override ValueTask<int> NonQueryExecutedAsync(DbCommand c,CommandExecutedEventData e,int result,CancellationToken ct=default){if(c.CommandText.Contains("INSERT INTO cerberus.record"))inserted=true;if(kind=="afterParent" && c.CommandText.Contains("UPDATE cerberus.profile") && result>0)throw new TimeoutException("synthetic post-parent failure");return ValueTask.FromResult(result);}
        public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<DbDataReader> r,CancellationToken ct=default){if(kind=="afterInsert" && inserted)throw new TimeoutException("synthetic post-insert failure");return ValueTask.FromResult(r);}
    }
}
